// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(address depositor, uint256 amt) public {
        vm.assume(depositor != address(0));
        amt = bound(amt, 1, 1 ether);

        vm.deal(depositor, amt * 2);
        vm.prank(depositor);
        c.deposit{value: amt}();

        bool ok1;
        vm.prank(depositor);
        try c.withdrawAll() {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        bool ok2;
        vm.prank(depositor);
        try c.withdrawAll() {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(ok1 && ok2);
    }
}
